// Resolve the account IDs in a confirmed receipt before synchronous panel parsers
// consume it. Keep amounts in raw chain units: each panel owns its unit boundary.
import { hasWalletIds } from '../chain/schema.js';
import { chainClient, contractInterface } from '../chain/client.js';
import { decorateWalletRows } from '../chain/wallet-events.js';
const decoded = new WeakMap();
export function walletReceiptLog(log, iface) { return decoded.get(log) ?? iface.parseLog(log); }
export async function prepareWalletReceipt(receipt, client = chainClient()) {
  if (!hasWalletIds() || !receipt?.logs?.length || receipt.blockNumber == null) return;
  const s = await client.snapshot({ blockTag: Number(receipt.blockNumber) });
  const contracts = new Map(Object.entries(client.contracts).map(([key, address]) => [String(address).toLowerCase(), key]));
  const rows = [];
  for (const log of receipt.logs) {
    const contract = contracts.get(String(log.address).toLowerCase());
    if (!contract) continue;
    const iface = await contractInterface(contract);
    let parsed;
    try { parsed = iface.parseLog(log); } catch { continue; }
    if (parsed) rows.push({ name: parsed.name, fragment: parsed.fragment, args: parsed.args, contract, log });
  }
  const decorated = await decorateWalletRows(s, row => row.contract, rows);
  await s.verify();
  for (const row of decorated) decoded.set(row.log, row);
}
